style.css:
@-moz-document regexp("https?://.*") {
/* Dit past de stijl toe op alle koppen van alle websites */
  h1, h2, h3, h4, h5, h6, .title, [class*="title"] {
    font-family: 'Arial Rounded MT Bold', 'Comic Sans MS', sans-serif !important;
    color: #CCCCFF !important; /* Echte diepe donkerpaars */
    
    /* Alle schaduwen en effecten volledig uitgeschakeld */
    text-shadow: none !important;
    box-shadow: none !important;
    
    /* Geen animaties */
    transition: none !important;
    animation: none !important;
  }
}
